import itertools
import json

def solve():
    houses = [1, 2, 3]

    Names = ["Arnold", "Eric", "Peter"]
    Flowers = ["carnations", "lilies", "daffodils"]
    HairColors = ["black", "brown", "blonde"]
    Sports = ["soccer", "basketball", "tennis"]
    HouseStyles = ["colonial", "ranch", "victorian"]
    Pets = ["fish", "dog", "cat"]

    solutions = []

    # Generate permutations for each category
    for hair in itertools.permutations(HairColors):
        # 2. The person who has blonde hair is in the second house.
        if hair[1] != "blonde":
            continue

        blonde_idx = hair.index("blonde")

        for flowers in itertools.permutations(Flowers):
            # 3. Daffodils <-> Blonde hair
            if flowers[blonde_idx] != "daffodils":
                continue
            # 7. Carnations is directly left of blonde hair
            if blonde_idx == 0:
                continue
            if flowers[blonde_idx - 1] != "carnations":
                continue

            for sports in itertools.permutations(Sports):
                # 8. Soccer is in the third house.
                if sports[2] != "soccer":
                    continue

                soccer_idx = 2
                basketball_idx = sports.index("basketball")

                for pets in itertools.permutations(Pets):
                    # 1. Cat <-> Soccer
                    if pets[soccer_idx] != "cat":
                        continue
                    # 6. Dog <-> Basketball
                    if pets[basketball_idx] != "dog":
                        continue

                    for styles in itertools.permutations(HouseStyles):
                        # 10. Colonial-style house is in the third house.
                        if styles[2] != "colonial":
                            continue

                        for names in itertools.permutations(Names):
                            # 4. Peter <-> Basketball
                            if names[basketball_idx] != "Peter":
                                continue

                            # 5. Arnold is directly left of the person in a ranch-style home.
                            if "ranch" not in styles:
                                continue
                            ranch_idx = styles.index("ranch")
                            # must have a house to the left of ranch
                            if ranch_idx == 0:
                                continue
                            if names[ranch_idx - 1] != "Arnold":
                                continue

                            # 9. Arnold is somewhere to the left of the person who has black hair.
                            arnold_idx = names.index("Arnold")
                            black_idx = hair.index("black")
                            if not (arnold_idx < black_idx):
                                continue

                            # All constraints satisfied; record solution
                            rows = []
                            for i in range(3):
                                row = [
                                    str(houses[i]),
                                    names[i],
                                    flowers[i],
                                    hair[i],
                                    sports[i],
                                    styles[i],
                                    pets[i],
                                ]
                                rows.append(row)

                            solutions.append({
                                "solution": {
                                    "header": ["House", "Name", "Flower", "HairColor", "FavoriteSport", "HouseStyle", "Pet"],
                                    "rows": rows
                                }
                            })

    # Assuming unique solution; output the first (or the only) solution
    if solutions:
        print(json.dumps(solutions[0], ensure_ascii=False))
    else:
        print(json.dumps({
            "solution": {
                "header": ["House", "Name", "Flower", "HairColor", "FavoriteSport", "HouseStyle", "Pet"],
                "rows": []
            }
        }))

if __name__ == "__main__":
    solve()
